private static String printOffset(int offset) {
    long absOffset = Math.abs((long) offset);
    int hours = (int) (absOffset / DateTimeConstants.MILLIS_PER_HOUR);
    int minutes = (int) ((absOffset / DateTimeConstants.MILLIS_PER_MINUTE) % 60);
    int seconds = (int) ((absOffset / DateTimeConstants.MILLIS_PER_SECOND) % 60);
    int millis = (int) (absOffset % DateTimeConstants.MILLIS_PER_SECOND);

    StringBuffer buf = new StringBuffer();
    buf.append(offset >= 0 ? '+' : '-');
    appendDigits(buf, hours);
    buf.append(':');
    appendDigits(buf, minutes);
    if (seconds != 0 || millis != 0) {
        buf.append(':');
        appendDigits(buf, seconds);
        if (millis != 0) {
            buf.append('.');
            appendDigits(buf, millis / 100);
            if (millis % 100 != 0) {
                appendDigits(buf, (millis / 10) % 10);
                if (millis % 10 != 0) {
                    appendDigits(buf, millis % 10);
                }
            }
        }
    }
    return buf.toString();
}

